import { spawn } from 'node:child_process';
const cmd = '/harness-state/.bun/bin/gbrain';
const args = ['serve', '--surface', 'starter', '--advertise', 'verbs'];
const p = spawn(cmd, args, { env: { ...process.env, GBRAIN_HOME: '/harness-state' }, stdio: ['pipe', 'pipe', 'pipe'] });
let buf = ''; const waiters = new Map(); let id = 0;
p.stdout.on('data', d => { buf += d; let i; while ((i = buf.indexOf('\n')) >= 0) { const line = buf.slice(0, i); buf = buf.slice(i + 1); if (!line.trim()) continue; try { const m = JSON.parse(line); if (m.id != null && waiters.has(m.id)) { waiters.get(m.id)(m); waiters.delete(m.id); } } catch {} } });
p.stderr.on('data', () => {});
const rpc = (method, params) => new Promise(r => { const i = ++id; waiters.set(i, r); p.stdin.write(JSON.stringify({ jsonrpc: '2.0', id: i, method, params }) + '\n'); });
const call = async (name, a) => { const r = await rpc('tools/call', { name, arguments: a }); return r.error ? { error: r.error } : (r.result.structuredContent ?? r.result.content?.map(c => c.text).join('\n')); };
const show = (label, v) => console.log(`--- ${label}\n` + (typeof v === 'string' ? v : JSON.stringify(v, null, 1)).slice(0, 1400));
const init = await rpc('initialize', { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'install-check', version: '1' } });
show('initialize', init.result?.serverInfo);
p.stdin.write(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' }) + '\n');
const tl = await rpc('tools/list', {});
show('tools', tl.result.tools.map(t => t.name));
const mode = process.argv[2];
if (mode === 'write') {
  show('remember', await call('remember', { fact: 'GBrain test note: keyless install on OpenClaw verified via MCP round trip', provenance: 'install-check-mcp', content_origin: 'agent_said' }));
}
show('recall', await call('recall', { query: process.argv[3] || 'GBrain test note' }));
p.kill(); process.exit(0);

